// MCPServiceError retains a native typed refusal; transport and uncertain-result errors remain errors.
func MCPServiceError(err error) ([]byte, bool) {
	if e, ok := err.(*ServiceError); ok {
		return encOAServiceError(nil, &oaServiceError{Code: string(e.Code), Message: e.Message}, 0), true
	}
	return nil, false
}

